import { describe, it, expect, beforeAll, afterAll } from 'vitest';
import postgres from 'postgres';

/**
 * RLS coverage (spec 4.3, migration 0280).
 *
 * The policies on every bastion_* table are GENERATED by a DO $$ loop over
 * information_schema, so a new table is covered automatically; this asserts the loop actually
 * ran against the live schema: all 35 tables of spec 4.1.1 exist, RLS is enabled on each, and
 * each carries exactly the org-isolation policy bound to app.current_org_id.
 *
 * Runs in CI's Vitest job (.github/workflows/test.yml, not db-drift.yml) against the migrated
 * service container; SKIPS LOUDLY without
 * DATABASE_URL.
 */

const DATABASE_URL = process.env.DATABASE_URL;

if (!DATABASE_URL) {
  console.warn(
    '[bastion-api/rls-coverage] SKIPPING: DATABASE_URL is not set, so per-table RLS policy ' +
      'coverage cannot be verified. Point DATABASE_URL at a migrated database.',
  );
}

// Spec 4.1.1, in order.
const SPEC_TABLES = [
  'bastion_frameworks',
  'bastion_controls',
  'bastion_control_requirements',
  'bastion_assertions',
  'bastion_compile_runs',
  'bastion_org_settings',
  'bastion_audit_log',
  'bastion_evaluation_runs',
  'bastion_evidence_objects',
  'bastion_object_intents',
  'bastion_evidence_snapshots',
  'bastion_manual_evidence',
  'bastion_manual_evidence_links',
  'bastion_evidence_feeds',
  'bastion_feed_keys',
  'bastion_feed_records',
  'bastion_personal_data',
  'bastion_ingest_events',
  'bastion_outbox',
  'bastion_ledger_entries',
  'bastion_ledger_seals',
  'bastion_ledger_restores',
  'bastion_drift_events',
  'bastion_gaps',
  'bastion_fix_drafts',
  'bastion_exceptions',
  'bastion_policies',
  'bastion_policy_attestations',
  'bastion_questionnaires',
  'bastion_questionnaire_items',
  'bastion_answer_library',
  'bastion_auditor_rooms',
  'bastion_auditor_access_log',
  'bastion_auditor_requests',
  'bastion_export_packets',
  // Added after spec 4.1.1: durable notice markers (migration 0287, issue #243).
  'bastion_notice_markers',
];

describe.skipIf(!DATABASE_URL)('bastion_* RLS policy coverage', () => {
  let sql: postgres.Sql;

  beforeAll(() => {
    sql = postgres(DATABASE_URL as string, { max: 2, onnotice: () => {} });
  });

  afterAll(async () => {
    if (sql) await sql.end({ timeout: 5 });
  });

  it('has exactly the 35 tables of spec 4.1.1 plus the later additions', async () => {
    const rows = await sql<Array<{ tablename: string }>>`
      SELECT tablename FROM pg_tables
       WHERE schemaname = 'public' AND tablename LIKE 'bastion\\_%'
       ORDER BY tablename`;
    expect(rows.map((r) => r.tablename)).toEqual([...SPEC_TABLES].sort());
  });

  it('every bastion_% table has RLS enabled and one org-isolation policy on app.current_org_id', async () => {
    const rows = await sql<Array<{ tablename: string; rowsecurity: boolean; policies: string[]; quals: string[] }>>`
      SELECT t.tablename,
             t.rowsecurity,
             coalesce(array_agg(p.policyname) FILTER (WHERE p.policyname IS NOT NULL), '{}') AS policies,
             coalesce(array_agg(p.qual) FILTER (WHERE p.policyname IS NOT NULL), '{}') AS quals
        FROM pg_tables t
        LEFT JOIN pg_policies p ON p.schemaname = 'public' AND p.tablename = t.tablename
       WHERE t.schemaname = 'public' AND t.tablename LIKE 'bastion\\_%'
       GROUP BY t.tablename, t.rowsecurity
       ORDER BY t.tablename`;
    expect(rows.length).toBe(SPEC_TABLES.length);
    const problems: string[] = [];
    for (const r of rows) {
      if (!r.rowsecurity) problems.push(`${r.tablename}: RLS disabled`);
      if (r.policies.length !== 1 || r.policies[0] !== `${r.tablename}_org_isolation`) {
        problems.push(`${r.tablename}: policies ${JSON.stringify(r.policies)}`);
      }
      if (!(r.quals[0] ?? '').includes('app.current_org_id')) problems.push(`${r.tablename}: qual ${r.quals[0]}`);
    }
    expect(problems).toEqual([]);
  });
});
